cat > src/contact.ts <<'EOF'
export interface ContactMessage { name: string, email: string, message: string }
export type ContactErrors = Partial<Record<keyof ContactMessage, string>>

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

export function checkContact(input: ContactMessage): ContactErrors {
  const name = input.name.trim()
  const email = input.email.trim()
  const message = input.message.trim()
  const errors: ContactErrors = {}

  if (name === '')
    errors.name = 'Name is required.'

  if (email === '')
    errors.email = 'Email is required.'
  else if (!emailPattern.test(email))
    errors.email = 'Enter a valid email address.'

  if (message.length < 20)
    errors.message = 'Message must be at least 20 characters.'

  return errors
}
EOF
cat > src/routes/contact.kay <<'EOF'
--- server
import { s } from 'kay'
import { checkContact } from '../contact'
import ContactForm from '../components/contact-form.kay'

const contactMessage = s.Object({
  name: s.String({ maxLength: 10000 }),
  email: s.String({ maxLength: 10000 }),
  message: s.String({ maxLength: 100000 }),
})

export const contact = action(contactMessage, (input, ctx) => {
  const errors = checkContact(input)

  if (Object.keys(errors).length > 0)
    return ctx.fail(422, { errors })

  return { name: input.name.trim() }
}, { bodyLimit: '1mb' })
---
head
  title Contact
h1 Contact
ContactForm
EOF
cat > src/components/contact-form.kay <<'EOF'
---
import { contact } from '../routes/contact.kay'
import { checkContact } from '../contact'
import type { ContactErrors } from '../contact'

const errors = signal<ContactErrors>(contact.failed()?.data?.errors ?? {})
const thanked = signal(contact.succeeded()?.data.name ?? '')

async function submit(event: SubmitEvent) {
  event.preventDefault()
  const form = event.currentTarget as HTMLFormElement
  const fields = new FormData(form)
  const found = checkContact({
    name: String(fields.get('name') ?? ''),
    email: String(fields.get('email') ?? ''),
    message: String(fields.get('message') ?? ''),
  })

  errors.set(found)
  thanked.set('')

  if (Object.keys(found).length === 0) {
    thanked.set((await contact(fields, { refresh: false })).name)
    form.reset()
  }
}
---
if thanked()
  p(role="status") Thanks, {thanked()}! Your message has been sent.
form(action={contact} novalidate onSubmit={submit})
  p
    label(for="contact-name") Name
    input#contact-name(type="text" name="name")
    if errors().name
      span.error {errors().name}
  p
    label(for="contact-email") Email
    input#contact-email(type="email" name="email")
    if errors().email
      span.error {errors().email}
  p
    label(for="contact-message") Message
    textarea#contact-message(name="message")
    if errors().message
      span.error {errors().message}
  button(type="submit") Send
EOF
